mapper.select:
select wtpd.MDATE-wtpd.VDATE actAmtDays, wtpd.TRADE_ID, #{VALID_STATUS_01} VALID_STATUS, wtpda.ENTRUST_ID, pp.PORTFOLIO_ID, pp.PORTFOLIO_NAME, wtpd.FINPROD_TYPE2, wtpdo.PLEDGE_FINPROD_ID, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR as FINPROD_NAME, wptpd.BACK_LEND_DIRECTION PS, wtpd.TRADE_MARKET, wtpdo.TERM_TYPE , wtpdo.PLEDGE_FACE_VALUE as TRADE_AMT, wtpd.CCY, wtpd.TRADE_DATE, wtpd.VDATE,wtpd.MDATE, wtpd.REMARK, wtpd.WORKFLOW_ID, wtpd.WORKFLOW_STATUS,NULL as EXCHANGE_PLEDGE from WFL_TRD_PRODUCT_DEAL wtpd left join WFL_TRD_PRODUCT_DEAL_ADD wtpda on wtpd.TRADE_ID = wtpda.TRADE_ID left join WFL_PA_TRD_PRODUCT_DEAL wptpd on wtpd.TRADE_ID = wptpd.TRADE_ID left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = wtpda.PORTFOLIO_ID left join WFL_TRD_PRODUCT_DEAL_OTH wtpdo on wtpd.TRADE_ID = wtpdo.TRADE_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = wtpdo.PLEDGE_FINPROD_ID where pp.INVEST_YESORNO='Y' AND wtpd.TOTLE_TRADE_ID IS NULL and wtpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F29}, #{FINPROD_TYPE_TG_F30}) AND wtpd.PS = #{psList}
AND (pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item} )
and (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND wtpda.ENTRUST_ID like CONCAT_WS('', #{entrustId}, '%')
AND wtpdo.PLEDGE_FINPROD_ID like CONCAT_WS('', #{finprodId}, '%')
AND wptpd.BACK_LEND_DIRECTION = #{ps}
AND wtpd.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin}, '%Y-%m-%d')
AND wtpd.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd}, '%Y-%m-%d')
and wtpd.TRADE_STATUS = #{TRADE_STATUS_01}
UNION ALL select wtpd.MDATE-wtpd.VDATE actAmtDays, wtpd.TRADE_ID, #{VALID_STATUS_02} VALID_STATUS, wtpda.ENTRUST_ID, pp.PORTFOLIO_ID, pp.PORTFOLIO_NAME, wtpd.FINPROD_TYPE2, fdt.PLEDGE_FINPROD_ID, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR as FINPROD_NAME, wptpd.BACK_LEND_DIRECTION PS, wtpd.TRADE_MARKET, ftp.TERM_TYPE , fdt.PLEDGE_FACE_VALUE as TRADE_AMT, wtpd.CCY, wtpd.TRADE_DATE, wtpd.VDATE,wtpd.MDATE, wtpd.REMARK, null as WORKFLOW_ID, null as WORKFLOW_STATUS,ftpa.EXCHANGE_PLEDGE from TRD_PRODUCT_DEAL wtpd left join TRD_PRODUCT_DEAL_ADD wtpda on wtpd.TRADE_ID = wtpda.TRADE_ID left join FIN_TRADE_PRODUCT ftp on wtpd.TRADE_ID = ftp.FINPROD_ID AND ftp.BRANCH = #{BRANCH_0} left join FIN_TRADE_PRODUCT_ADD ftpa on ftpa.FINPROD_ID = ftp.FINPROD_ID left join PA_TRD_PRODUCT_DEAL wptpd on wtpd.TRADE_ID = wptpd.TRADE_ID left join FIN_DEAL_TARGET fdt on wtpd.TRADE_ID = fdt.FINPROD_ID AND fdt.BRANCH = #{BRANCH_0} left join PTL_TRADE PT ON wtpd.TRADE_ID = PT.BUSI_NO left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = PT.PORTFOLIO_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = fdt.PLEDGE_FINPROD_ID where pp.INVEST_YESORNO='Y' AND wtpd.TOTLE_TRADE_ID IS NULL AND wtpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F29}, #{FINPROD_TYPE_TG_F30}) AND wtpd.PS = #{psList}
AND (pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item} )
and (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND wtpda.ENTRUST_ID like CONCAT_WS('', #{entrustId}, '%')
AND fdt.PLEDGE_FINPROD_ID like CONCAT_WS('', #{finprodId}, '%')
AND wptpd.BACK_LEND_DIRECTION = #{ps}
AND wtpd.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin}, '%Y-%m-%d')
AND wtpd.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd}, '%Y-%m-%d')
and (wtpd.IS_CANCEL is null or wtpd.IS_CANCEL = #{YES_NO_NO}) and wtpd.TRADE_STATUS = #{TRADE_STATUS_01}
UNION ALL select wtpd.MDATE-wtpd.VDATE actAmtDays, wtpd.TRADE_ID, #{VALID_STATUS_03} VALID_STATUS, wtpda.ENTRUST_ID, pp.PORTFOLIO_ID, pp.PORTFOLIO_NAME, wtpd.FINPROD_TYPE2, fdt.PLEDGE_FINPROD_ID, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR as FINPROD_NAME, wptpd.BACK_LEND_DIRECTION PS, wtpd.TRADE_MARKET, ftp.TERM_TYPE , fdt.PLEDGE_FACE_VALUE as TRADE_AMT, wtpd.CCY, wtpd.TRADE_DATE, wtpd.VDATE,wtpd.MDATE, wtpd.REMARK, null as WORKFLOW_ID, null as WORKFLOW_STATUS,NULL as EXCHANGE_PLEDGE from TRD_PRODUCT_DEAL wtpd left join TRD_PRODUCT_DEAL_ADD wtpda on wtpd.TRADE_ID = wtpda.TRADE_ID left join FIN_TRADE_PRODUCT ftp on wtpd.TRADE_ID = ftp.FINPROD_ID AND ftp.BRANCH = #{BRANCH_0} left join PA_TRD_PRODUCT_DEAL wptpd on wtpd.TRADE_ID = wptpd.TRADE_ID left join FIN_DEAL_TARGET fdt on wtpd.TRADE_ID = fdt.FINPROD_ID AND fdt.BRANCH = #{BRANCH_0} left join PTL_TRADE PT ON wtpd.TRADE_ID = PT.busi_No left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = PT.PORTFOLIO_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = fdt.PLEDGE_FINPROD_ID where pp.INVEST_YESORNO='Y' AND wtpd.TOTLE_TRADE_ID IS NULL AND wtpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F29}, #{FINPROD_TYPE_TG_F30}) AND wtpd.PS = #{psList}
AND (pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item} )
and (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND wtpda.ENTRUST_ID like CONCAT_WS('', #{entrustId}, '%')
AND fdt.PLEDGE_FINPROD_ID like CONCAT_WS('', #{finprodId}, '%')
AND wptpd.BACK_LEND_DIRECTION = #{ps}
AND wtpd.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin}, '%Y-%m-%d')
AND wtpd.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd}, '%Y-%m-%d')
and wtpd.IS_CANCEL = #{YES_NO_YES} and wtpd.TRADE_STATUS = #{TRADE_STATUS_01}
ORDER BY TRADE_DATE DESC, TRADE_ID DESC

SELECT A.FINPROD_ID id, A.FINPROD_MARKET_ID text, A.FINPROD_ID, A.FINPROD_NAME, DATE_FORMAT(A.VDATE, '%Y-%m-%d') VDATE, DATE_FORMAT(A.MDATE, '%Y-%m-%d') MDATE, DATE_FORMAT(A.IDATE, '%Y-%m-%d') IDATE, A.TRADE_MARKET, A.CCY, A.CALENDAR_ID, basisData.BASIS, B.TYPE_4 windtypeone, A.FINPROD_MARKET_ID, A.IS_RIGHT FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID LEFT JOIN ( select max(BASIS) as BASIS, FINPROD_ID from FIN_CASH_CALC_RULE
AND FINPROD_ID = #{initValue}
group by FINPROD_ID ) basisData on A.FINPROD_ID = basisData.FINPROD_ID
( A.FINPROD_MARKET_ID LIKE CONCAT_WS('', '%', #{search}, '%') or A.FINPROD_NAME LIKE CONCAT_WS('', '%', #{search}, '%') )
AND A.FINPROD_ID = #{initValue}
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND B.TYPE_4 = #{windtypeone}
AND A.TRADE_MARKET = #{FINPROD_MARKET}
union select interf.SECID id, interf.SECID text, fin.FINPROD_ID, interf.SECNAME FINPROD_NAME, null, null, null, null, null, null, null, null, null, null from interf_payhsrcsecinfo interf left join fin_product fin on interf.SECID = fin.FINPROD_ID where SECID not in (select FINPROD_MARKET_ID from fin_product A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND B.TYPE_4 = #{windtypeone}
)
AND interf.SECID = #{initValue}
and ( interf.SECID LIKE CONCAT_WS('', '%', #{search}, '%') or interf.SECNAME LIKE CONCAT_WS('', '%', #{search}, '%') )
AND interf.MARKET = #{FINPROD_WIND_MARKET}
